Here is a tiny key-value store with an in-memory index. It has a bug that returns wrong values after a few writes. Find it and fix it.

```js
const fs = require('fs');
const index = new Map();
let offset = 0;

function set(key, value) {
  const line = JSON.stringify([key, value]) + '\n';
  fs.appendFileSync('db.log', line);
  index.set(key, offset);
  offset += line.length;
}

function get(key) {
  if (!index.has(key)) return undefined;
  const buf = fs.readFileSync('db.log');
  const start = index.get(key);
  const end = buf.indexOf('\n', start);
  return JSON.parse(buf.subarray(start, end).toString())[1];
}
```
